// WebCineTV service worker.
// The file keeps its historical name (/sw.min.js) so existing registrations
// update in place instead of leaving an orphaned worker behind.
//
// Responsibilities:
// 1. WebTorrent streaming (/webtorrent/*) - unchanged behaviour.
// 2. PWA app shell, deliberately minimal for a realtime app:
//    - /assets/* (content-hashed JS/CSS/fonts/images): cache-first.
//    - Page navigations: network-first; only when the network fails the
//      precached /offline.html is shown. HTML pages are never cached.
//    - Everything else (API, /socket.io, WebRTC signaling, /webrtc/ice, room
//      data, media streams, cross-origin requests, non-GET) is NOT handled
//      here and goes straight to the network.
// BUILD_ID is stamped at build time (vite.config.ts) so every deploy ships a
// byte-different worker: it installs, skips waiting and claims the clients.
(() => {
  "use strict";

  const BUILD_ID = "__WEBCINE_BUILD_ID__";
  const SHELL_CACHE = "webcine-shell-" + BUILD_ID;
  const ASSET_CACHE = "webcine-assets-v1";
  const OFFLINE_URL = "/offline.html";
  const MAX_ASSET_ENTRIES = 120;

  // ---------------------------------------------------------------------
  // WebTorrent streaming
  // ---------------------------------------------------------------------
  let cancelled = false;

  function webtorrentResponse(event) {
    const { url } = event.request;
    const scope = self.registration.scope;
    if (!url.includes(scope + "webtorrent/")) {
      return null;
    }
    if (url.includes(scope + "webtorrent/keepalive/")) {
      return new Response();
    }
    if (url.includes(scope + "webtorrent/cancel/")) {
      return new Response(
        new ReadableStream({
          cancel() {
            cancelled = true;
          },
        }),
      );
    }
    return (async function ({ request }) {
      const { url, method, headers, destination } = request;
      const windows = await clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      const [data, port] = await new Promise((resolve) => {
        for (const client of windows) {
          const channel = new MessageChannel();
          const { port1, port2 } = channel;
          port1.onmessage = ({ data }) => {
            resolve([data, port1]);
          };
          client.postMessage(
            {
              url,
              method,
              headers: Object.fromEntries(headers.entries()),
              scope: self.registration.scope,
              destination,
              type: "webtorrent",
            },
            [port2],
          );
        }
      });
      let timeout = null;
      const cleanup = () => {
        port.postMessage(false);
        clearTimeout(timeout);
        port.onmessage = null;
      };
      if (data.body !== "STREAM") {
        cleanup();
        return new Response(data.body, data);
      }
      return new Response(
        new ReadableStream({
          pull: (controller) =>
            new Promise((resolve) => {
              port.onmessage = ({ data }) => {
                if (data) {
                  controller.enqueue(data);
                } else {
                  cleanup();
                  controller.close();
                }
                resolve();
              };
              if (!cancelled) {
                clearTimeout(timeout);
                if (destination !== "document") {
                  timeout = setTimeout(() => {
                    cleanup();
                    resolve();
                  }, 5000);
                }
              }
              port.postMessage(true);
            }),
          cancel() {
            cleanup();
          },
        }),
        data,
      );
    })(event);
  }

  // ---------------------------------------------------------------------
  // App shell
  // ---------------------------------------------------------------------
  async function trimAssetCache() {
    const cache = await caches.open(ASSET_CACHE);
    const keys = await cache.keys();
    // Cache.keys() is in insertion order: drop the oldest entries.
    const excess = keys.length - MAX_ASSET_ENTRIES;
    for (let i = 0; i < excess; i++) {
      await cache.delete(keys[i]);
    }
  }

  async function assetResponse(request) {
    const cache = await caches.open(ASSET_CACHE);
    const cached = await cache.match(request);
    if (cached) {
      return cached;
    }
    const response = await fetch(request);
    if (response.ok && response.status === 200 && response.type === "basic") {
      cache.put(request, response.clone()).catch(() => undefined);
    }
    return response;
  }

  async function navigationResponse(event) {
    try {
      const preloaded = await event.preloadResponse;
      if (preloaded) {
        return preloaded;
      }
      return await fetch(event.request);
    } catch (error) {
      const cache = await caches.open(SHELL_CACHE);
      const offline = await cache.match(OFFLINE_URL);
      if (offline) {
        return offline;
      }
      throw error;
    }
  }

  function shellResponse(event) {
    const { request } = event;
    if (request.method !== "GET") {
      return null;
    }
    const url = new URL(request.url);
    if (url.origin !== self.location.origin) {
      return null;
    }
    if (request.mode === "navigate") {
      return navigationResponse(event);
    }
    if (url.pathname.startsWith("/assets/") && !request.headers.has("range")) {
      return assetResponse(request);
    }
    return null;
  }

  self.addEventListener("install", (event) => {
    self.skipWaiting();
    event.waitUntil(
      caches
        .open(SHELL_CACHE)
        // A failed precache must not block the worker (WebTorrent needs it).
        .then((cache) =>
          cache.add(new Request(OFFLINE_URL, { cache: "reload" })),
        )
        .catch(() => undefined),
    );
  });

  self.addEventListener("activate", (event) => {
    event.waitUntil(
      (async () => {
        const names = await caches.keys();
        await Promise.all(
          names
            .filter(
              (name) => name.startsWith("webcine-shell-") && name !== SHELL_CACHE,
            )
            .map((name) => caches.delete(name)),
        );
        await trimAssetCache().catch(() => undefined);
        if (self.registration.navigationPreload) {
          await self.registration.navigationPreload
            .enable()
            .catch(() => undefined);
        }
        await self.clients.claim();
      })(),
    );
  });

  self.addEventListener("fetch", (event) => {
    const response = webtorrentResponse(event) || shellResponse(event);
    if (response) {
      event.respondWith(response);
    }
  });
})();
